from collections import deque
import sys


def read_lines():
    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


def print_order(jobs):
    urgent = deque()
    normal = deque()
    for job in jobs:
        name, prio = job.split()
        if prio == "1":
            urgent.append(name)
        else:
            normal.append(name)
    out = []
    while urgent:
        out.append(urgent.popleft())
    while normal:
        out.append(normal.popleft())
    return out


def main():
    lines = read_lines()
    jobs = lines[1:]
    print(' '.join(print_order(jobs)))


main()

import sys


def read_lines():
    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


def circular_queue_ops(cap, ops):
    buf = [None] * cap
    head = 0
    count = 0
    res = []
    for op in ops:
        parts = op.split()
        if parts[0] == "enq":
            if count < cap:
                buf[(head + count) % cap] = int(parts[1])
                count += 1
        elif parts[0] == "deq":
            if count == 0:
                res.append("EMPTY")
            else:
                res.append(buf[head])
                head = (head + 1) % cap
                count -= 1
        else:
            res.append("EMPTY" if count == 0 else buf[head])
    return res


def main():
    lines = read_lines()
    cap = int(lines[0])
    ops = lines[2:]
    print('\n'.join(map(str, circular_queue_ops(cap, ops))))


main()

