def fives_sixes(n):
    res = []
    q = deque()
    for seed in (5, 6):
        if seed <= n:
            q.append(seed)
    while q:
        x = q.popleft()
        res.append(x)
        for d in (5, 6):
            y = x * 10 + d
            if y <= n:
                q.append(y)
    return res


def main():
    lines = read_lines()
    n = int(lines[0])
    print('\n'.join(map(str, fives_sixes(n))))


main()

