def first_negatives(nums, k):
    dq = deque()
    res = []
    for i, x in enumerate(nums):
        if x < 0:
            dq.append(i)
        if i >= k and dq and dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            res.append(nums[dq[0]] if dq else 0)
    return res


def main():
