    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


def stream_chars(s):
    count = {}
    q = deque()
    res = []
    for ch in s:
        count[ch] = count.get(ch, 0) + 1
        q.append(ch)
        while q and count[q[0]] > 1:
            q.popleft()
        res.append(q[0] if q else "-")
    return res


def main():
    lines = read_lines()
    print('\n'.join(stream_chars(lines[0])))


